import{z as A,x as s,o as t,c as p,q as n,j as l,D as E,d as r,s as o,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"前缀感知扩缩容","description":"","frontmatter":{"title":"前缀感知扩缩容","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/prefix-aware-autoscaling.md","filePath":"llm/prefix-aware-autoscaling.md","lastUpdated":1791413859000}'),D={name:"llm/prefix-aware-autoscaling.md"};function d(h,a,P,m,c,C){const i=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="前缀感知扩缩容" tabindex="-1">前缀感知扩缩容 <a class="header-anchor" href="#前缀感知扩缩容" aria-label="Permalink to &quot;前缀感知扩缩容&quot;">​</a></h1><div class="epigraph"><p>热前缀打满一张卡时，正确的扩容是把这段 KV 复制到更多 GPU，而不是再开一个空副本去把同一段提示重算一遍。</p><footer>—— Srivatsa 等，Preble：对流行前缀做自动复制；对照 DistServe 按阶段独立加副本</footer></div><p>水平扩展对无状态 HTTP 是加机器、摊请求。对带 KV 的语言模型，新副本是空的：系统提示、工具说明书、文档前缀都要重新预填充，集群越大，随机路由把同一前缀打散得越碎，单机 <a href="/llm/prefix-caching">前缀缓存</a> 的命中率按 \\(1/R\\) 掉。前缀感知扩缩容把「副本数」和「某段 KV 的副本数」分开：流量涨时，先复制已经算好的热前缀，而不是只加冷实例；流量降时，先收叶子、再收根，避免把所有人还在用的系统提示从集群里删掉。本篇写这一层控制面，路由键见 <a href="/llm/kv-aware-routing">KV 感知路由</a>，单机树见 <a href="/llm/radix-attention">RadixAttention</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Srivatsa、He、Abhyankar、Li、Zhang 等人的 Preble（arXiv:2407.00023，后续 ICLR 2025）指出：生产流量里提示远长于生成，且 85%–97% 的提示 token 与其他请求共享。单卡前缀缓存（vLLM、SGLang）已经能复用；分布式默认却按算力均分，共享前缀被送到不同 GPU，KV 在每张卡上各算一份。若矫枉过正、永远把共享前缀打到同一张卡，那张卡成为热点，队列爆炸。Preble 的 E2 算法在「利用已有前缀」与「探索更空的卡」之间按节省的预填充是否大于新计算来选；当单个前缀的负载超过一张卡，系统<strong>自动扩展该前缀</strong>——把 KV 复制到更多 GPU 并按子树切负载。</p><p>这与 DistServe（Zhong 等，OSDI 2024）的「按阶段扩」互补。DistServe 让预填充池与解码池独立加 GPU，因为 TTFT 与 TPOT 的资源形态不同。前缀感知是在同一阶段内部：预填充池里也要决定「这段 8K 系统提示该有几份缓存」。Mooncake 的 KV 中心调度在过载时用预测做提前拒绝，同样假设调度器看得见缓存位置；看不见位置的 HPA（只看 GPU 利用率）会在缓存命中最高的时候错误地加冷副本，把命中率打下去，利用率看起来更「需要再扩」。</p><p><span class="marginnote">「按阶段扩」翻译成白话：预填充是「一口气读完整段提示」的重活，解码是「一个字一个字往外蹦」的细活，两者吃的资源不一样，所以分成两拨机器各自加副本，比混在一起按总请求数扩更省。TTFT 指从发出请求到看到第一个字的时间，TPOT 指之后每多吐一个字要等的时间。</span></p><h3 id="利用率不是正确的扩容信号" tabindex="-1">利用率不是正确的扩容信号 <a class="header-anchor" href="#利用率不是正确的扩容信号" aria-label="Permalink to &quot;利用率不是正确的扩容信号&quot;">​</a></h3><p>一张卡 HBM 很满、SM 很忙，可能是因为它持有热前缀、正在用缓存吃高 QPS——再加冷副本会分流走本该命中的请求。另一张卡很闲，可能只是还没分到任何热前缀。按 GPU 指标扩缩，会在错误的时间制造冷启动。正确信号是：该前缀的队列延迟、可复用 token 数、以及「再复制一份 KV 的传输成本」对比「重算这份 KV 的成本」。</p><p><span class="marginnote">复制前缀不是复制模型权重。权重本来每张卡都有一份；复制的是激活态 KV，体积随长度线性涨。8K 前缀在 MLA/GQA 下仍可能数十到数百 MB 每层合计，复制本身要走 <a href="/llm/kv-rdma-fetch">RDMA 拉取</a>。扩容决策必须把这次拷贝算进 SLO。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="利用、探索、再复制" tabindex="-1">利用、探索、再复制 <a class="header-anchor" href="#利用、探索、再复制" aria-label="Permalink to &quot;利用、探索、再复制&quot;">​</a></h3><p>E2 的利用：新请求的最长公共前缀已经在某 GPU 上，且省下的预填充大于把请求放到别处的收益，则送到该 GPU。探索：共享段短、或目标卡已经过载，则选「前缀感知负载」最低的 GPU——负载计入近期算力、驱逐代价、以及新请求在该卡上因命中而免掉的计算。自动扩展：重平衡之后，某前缀的平均排队仍在恶化，则把该前缀的 KV 复制到另一张卡，并把子树按负载切开。缩容相反：副本的命中跌到阈值以下，先停止新调度，等引用计数归零再释放块，最后才下线实例。</p><p>控制面要维护「前缀指纹 → 持有者列表」，与引擎块表同一套哈希（chat template 之后的 token id，外加模型、LoRA、模板版本）。Mooncake Conductor 一类索引器按实例返回最长匹配与介质；扩容进程是这条表上的写者：复制完成后才把新持有者发布出去，否则路由会把请求送到块表尚未插入的副本上，造成假命中。</p><p><span class="marginnote">「前缀指纹」常见误区：初学者容易以为只哈希提示文本就够了。实际上同一个提示换了 chat template、换了模型或换了 LoRA 适配器，算出的 KV 并不通用，文本指纹却完全相同——路由把请求送过去，等来的仍是一次全量重算。指纹必须把模型、模板、适配器版本一起拼进 key。</span></p><h3 id="与-pd-分离的两级扩容" tabindex="-1">与 PD 分离的两级扩容 <a class="header-anchor" href="#与-pd-分离的两级扩容" aria-label="Permalink to &quot;与 PD 分离的两级扩容&quot;">​</a></h3><p>预填充池按「未命中 token 的算力」扩，解码池按「并发会话的 KV 体积与 TPOT」扩。前缀命中高的流量，在 Preble 的叙述里更接近解码形态（几乎不必再预填充），应避免再往预填充池扔。DistServe 按 TTFT/TPOT 约束分别选并行度再复制实例；前缀感知在复制时优先克隆已有 KV 的实例镜像，而不是从检查点冷拉起一个空 worker。滚动升级等于定期缩容热前缀，必须先迁缓存或接受一次性 TTFT 回归。</p>',17)),(t(),l(B,null,{default:E(()=>[o(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%96%B0%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20M%5B%22%E6%9C%80%E9%95%BF%E5%89%8D%E7%BC%80%E5%8C%B9%E9%85%8D%22%5D%0A%20%20M%20--%3E%20E2%7B%22%E5%88%A9%E7%94%A8%E8%BF%98%E6%98%AF%E6%8E%A2%E7%B4%A2%22%7D%0A%20%20E2%20--%3E%7C%22%E9%95%BF%E5%91%BD%E4%B8%AD%E4%B8%94%E7%9B%AE%E6%A0%87%E6%9C%AA%E8%BF%87%E8%BD%BD%22%7C%20HIT%5B%22%E9%80%81%E5%88%B0%E6%8C%81%E6%9C%89%E8%80%85%22%5D%0A%20%20E2%20--%3E%7C%22%E7%9F%AD%E5%91%BD%E4%B8%AD%E6%88%96%E8%BF%87%E8%BD%BD%22%7C%20EXP%5B%22%E9%80%81%E5%88%B0%E5%89%8D%E7%BC%80%E6%84%9F%E7%9F%A5%E8%B4%9F%E8%BD%BD%E6%9C%80%E4%BD%8E%E7%9A%84%E5%8D%A1%22%5D%0A%20%20HIT%20--%3E%20MON%5B%22%E7%9B%91%E6%8E%A7%E8%AF%A5%E5%89%8D%E7%BC%80%E6%8E%92%E9%98%9F%22%5D%0A%20%20MON%20--%3E%7C%22%E6%8C%81%E7%BB%AD%E8%BF%87%E8%BD%BD%22%7C%20REP%5B%22RDMA%20%E5%A4%8D%E5%88%B6%20KV%20%E5%88%B0%E6%96%B0%E5%89%AF%E6%9C%AC%22%5D%0A%20%20REP%20--%3E%20PUB%5B%22%E7%B4%A2%E5%BC%95%E5%99%A8%E7%99%BB%E8%AE%B0%E6%96%B0%E6%8C%81%E6%9C%89%E8%80%85%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("h3",{id:"为什么复制比重算更值",tabindex:"-1"},[r("为什么复制比重算更值 "),e("a",{class:"header-anchor",href:"#为什么复制比重算更值","aria-label":'Permalink to "为什么复制比重算更值"'},"​")],-1)),a[5]||(a[5]=e("p",null,"预填充代价随未命中长度 \\(n-p\\) 走，注意力部分还带二次项。复制代价随已有 KV 字节 \\(M\\) 与链路带宽走，且可与后续请求重叠。当 \\(p\\) 接近 \\(n\\)、QPS 高，一份 KV 被反复读，复制的摊销成本按 \\(1/\\mathrm{QPS}\\) 下降。当 \\(p\\) 很小，复制几乎等于搬一整段马上要重算的东西，不如探索空卡。E2 用「共享 token 是否多于剩余 token」做一阶启发式，正是在比较这两条屋顶线。",-1)),(t(),l(B,null,{default:E(()=>[o(i,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E4%B8%80%E6%89%B9%E6%96%B0%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20CMP%7B%22%E5%91%BD%E4%B8%AD%E9%95%BF%E5%BA%A6%20p%20%E6%8E%A5%E8%BF%91%E6%80%BB%E9%95%BF%20n%3F%22%7D%0A%20%20CMP%20--%3E%7C%22%E6%98%AF%22%7C%20HIGH%5B%22%E9%AB%98%E5%91%BD%E4%B8%AD%3A%20%E4%B8%80%E4%BB%BD%20KV%20%E8%A2%AB%E5%8F%8D%E5%A4%8D%E8%AF%BB%22%5D%0A%20%20HIGH%20--%3E%20QPS%7B%22QPS%20%E9%AB%98%3F%22%7D%0A%20%20QPS%20--%3E%7C%22%E6%98%AF%22%7C%20CPY%5B%22%E5%A4%8D%E5%88%B6%20KV%3A%20%E6%91%8A%E9%94%80%E6%88%90%E6%9C%AC%E9%9A%8F%20QPS%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20QPS%20--%3E%7C%22%E5%90%A6%22%7C%20HOLD%5B%22%E7%BB%B4%E6%8C%81%E5%8D%95%E5%89%AF%E6%9C%AC%E8%A7%82%E5%AF%9F%E6%8E%92%E9%98%9F%22%5D%0A%20%20CMP%20--%3E%7C%22%E5%90%A6%22%7C%20LOW%5B%22%E4%BD%8E%E5%91%BD%E4%B8%AD%3A%20%E5%A4%8D%E5%88%B6%E8%BF%91%E4%BC%BC%E9%87%8D%E7%AE%97%22%5D%0A%20%20LOW%20--%3E%20EXP%5B%22%E6%8E%A2%E7%B4%A2%E7%A9%BA%E5%8D%A1%3A%20%E5%9D%87%E8%A1%A1%E7%AE%97%E5%8A%9B%22%5D%0A%20%20CPY%20--%3E%20SUB%5B%22%E4%BB%8D%E8%BF%87%E8%BD%BD%3A%20%E6%8C%89%E5%AD%90%E6%A0%91%E5%88%87%E8%B4%9F%E8%BD%BD%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">直觉类比：复制 KV 像把图书馆的热门参考书再印一本放进分馆，成本是一次搬运；不复制则像每来一位读者都从头把书重写一遍。读者越多（QPS 越高），复印一次服务越多人就越划算；而一本几乎没人借的冷书，复印纯属浪费——这正是低命中流量该去「探索空卡」的原因。</span></p><p>公平性不能丢。只按命中率调度会让短提示、冷用户永远排在热前缀后面。Preble 按命中率分优先级再给配额，避免多租户里某个系统提示独占集群。扩缩容若只服务热前缀，冷启动租户会在扩容事件里被饿死——控制面应保留一定比例的探索容量。</p><p><span class="marginnote">缩容最容易写错：HPA 看到利用率低就杀 pod，杀的恰好是持有根前缀的那张卡，集群立刻回到全量预填充。正确顺序是：摘流量 → 等 in-flight 结束 → 可选把根前缀迁到幸存者 → 再删实例。</span></p><h3 id="缓存感知调度是扩容的微观形式" tabindex="-1">缓存感知调度是扩容的微观形式 <a class="header-anchor" href="#缓存感知调度是扩容的微观形式" aria-label="Permalink to &quot;缓存感知调度是扩容的微观形式&quot;">​</a></h3><p>Zheng 等人在 SGLang 里按最长共享前缀排序请求，是单卡上的「把热子树走完」。集群扩容是同一原则的宏观形式：先让热前缀有足够副本，再让空闲算力去探索。没有微观调度，多副本上的块会被无关流量挤出 HBM，复制等于白做。没有宏观扩容，微观调度只能在一张过载卡上排队。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Preble 的 1.5×–14.5× 延迟数字绑在他们的五类长提示负载、Azure 到达过程、以及 A6000/H100 规模上，不能当成任意聊天机器人的保修。短提示、无共享、纯解码主导的流量，前缀感知扩容几乎没有杠杆，回到 DistServe 式按阶段扩即可。索引器是单点风险：它滞后会导致假命中，必须与引擎的 BlockStored/BlockRemoved 事件同事务。</p><p>不要用用户 ID 粘滞代替前缀指纹。不要在 LoRA 多适配器上只哈希文本。不要假设复制 KV 与复制容器镜像是同一 K8s 对象——前者要走传输引擎，后者只是权重。</p><p><span class="marginnote">出处：Srivatsa 等，<em>Preble: Efficient Distributed Prompt Scheduling for LLM Serving</em>，arXiv:2407.00023；Zhong 等 DistServe，OSDI 2024；Qin 等 Mooncake；Zheng 等 SGLang RadixAttention。没有一篇名叫「prefix-aware autoscaling」的必须伪造的经典论文，产品名应落到上述系统。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前缀感知扩缩容复制的是热 KV，而不只是冷的模型副本。</li><li>利用已有命中、探索空卡、过载时复制前缀，三者缺一就会热点或冷启动。</li><li>GPU 利用率不是可靠信号；看该前缀的排队与复用 token 数。</li><li>与 PD 分离叠加时，命中流量更像解码，不要盲目加预填充卡。</li><li>缩容必须先迁或放弃根前缀，再删实例。</li><li>出处：Preble；DistServe；Mooncake；SGLang。</li></ul>',11))])}const S=A(D,[["render",d]]);export{u as __pageData,S as default};
